#!/usr/bin/env python3
from __future__ import annotations

import argparse
from pathlib import Path


def replace_once(text: str, old: str, new: str, *, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"expected exactly one {label} anchor, found {count}")
    return text.replace(old, new, 1)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo-root", type=Path, required=True)
    args = parser.parse_args()
    repo = args.repo_root.resolve()
    pipeline = repo / "tools/scrapling_provider_pipeline"
    contract = pipeline / "cache_contract.py"
    build = pipeline / "build_provider_cache.py"
    test = pipeline / "tests/test_legacy_baseline_preflight.py"

    contract_text = contract.read_text(encoding="utf-8")
    old = '''def load_legacy_baseline(\n    cache: dict[str, Any] | None,\n    available_path: Path,\n    modes_path: Path,\n) -> dict[str, CatalogEntry]:\n    if isinstance(cache, dict):\n        baseline = entries_from_json(cache.get("legacyBaseline"))\n        if baseline:\n            return baseline\n    available = load_json(available_path, [])\n'''
    new = '''def load_legacy_baseline(\n    cache: dict[str, Any] | None,\n    available_path: Path,\n    modes_path: Path,\n) -> dict[str, CatalogEntry]:\n    if isinstance(cache, dict) and cache.get("schemaVersion") == SCHEMA_VERSION:\n        raw_baseline = cache.get("legacyBaseline")\n        if not isinstance(raw_baseline, list):\n            raise ValueError("compatible provider cache is missing legacyBaseline list")\n        for index, item in enumerate(raw_baseline):\n            if not isinstance(item, dict):\n                raise ValueError(f"legacyBaseline[{index}] must be an object")\n            title = item.get("title")\n            if (\n                not isinstance(title, str)\n                or not title.strip()\n                or normalize_title(title) != title\n            ):\n                raise ValueError(f"legacyBaseline[{index}] title is not canonical")\n            if type(item.get("sub")) is not bool or type(item.get("dub")) is not bool:\n                raise ValueError(f"legacyBaseline[{index}] modes must be boolean")\n        baseline = entries_from_json(raw_baseline)\n        if len(baseline) != len(raw_baseline):\n            raise ValueError("legacyBaseline contains duplicate normalized titles")\n        # An explicitly empty baseline is valid. Never fall back to the merged\n        # availability list once a compatible provider cache exists; doing so\n        # would promote provider-owned titles into permanent legacy provenance.\n        return baseline\n    available = load_json(available_path, [])\n'''
    contract_text = replace_once(contract_text, old, new, label="legacy baseline loader")
    contract.write_text(contract_text, encoding="utf-8")

    build_text = build.read_text(encoding="utf-8")
    old_cache = '''    old_cache = load_json(paths["cache"], {})\n    preserved_unselected: dict[str, Any] = {}\n'''
    new_cache = '''    cache_path_exists = paths["cache"].exists()\n    old_cache = load_json(paths["cache"], None)\n    if cache_path_exists and (\n        not isinstance(old_cache, dict) or old_cache.get("schemaVersion") != 1\n    ):\n        raise SystemExit("Existing provider cache is malformed or incompatible")\n    if old_cache is None:\n        old_cache = {}\n    preserved_unselected: dict[str, Any] = {}\n'''
    build_text = replace_once(build_text, old_cache, new_cache, label="existing cache preflight")
    old_baseline = '''    baseline = load_legacy_baseline(old_cache, paths["available"], paths["modes"])\n    fetcher = ScraplingFetcher(\n'''
    new_baseline = '''    try:\n        baseline = load_legacy_baseline(old_cache, paths["available"], paths["modes"])\n    except ValueError as error:\n        raise SystemExit(f"Legacy baseline preflight failed: {error}") from None\n    fetcher = ScraplingFetcher(\n'''
    build_text = replace_once(build_text, old_baseline, new_baseline, label="baseline preflight boundary")
    build.write_text(build_text, encoding="utf-8")

    if test.exists():
        raise SystemExit("legacy baseline test file already exists")
    test.write_text('''from __future__ import annotations\n\nimport importlib.util\nimport json\nimport sys\nimport tempfile\nimport unittest\nfrom pathlib import Path\nfrom unittest.mock import patch\n\nPIPELINE = Path(__file__).resolve().parents[1]\nif str(PIPELINE) not in sys.path:\n    sys.path.insert(0, str(PIPELINE))\n\nfrom cache_contract import load_legacy_baseline\n\nMODULE_PATH = PIPELINE / "build_provider_cache.py"\nspec = importlib.util.spec_from_file_location("legacy_baseline_provider_cache", MODULE_PATH)\nprovider_cache = importlib.util.module_from_spec(spec)\nassert spec.loader is not None\nsys.modules[spec.name] = provider_cache\nspec.loader.exec_module(provider_cache)\n\n\nclass LegacyBaselinePreflightTests(unittest.TestCase):\n    def test_empty_cached_baseline_stays_empty_instead_of_using_merged_available(self):\n        with tempfile.TemporaryDirectory() as temp:\n            root = Path(temp)\n            available = root / "available.json"\n            modes = root / "modes.json"\n            available.write_text(json.dumps(["provider only"]), encoding="utf-8")\n            modes.write_text(json.dumps({"provider only": {"sub": True, "dub": False}}), encoding="utf-8")\n            baseline = load_legacy_baseline(\n                {"schemaVersion": 1, "legacyBaseline": []},\n                available,\n                modes,\n            )\n            self.assertEqual(baseline, {})\n\n    def test_missing_cached_baseline_is_rejected(self):\n        with tempfile.TemporaryDirectory() as temp:\n            root = Path(temp)\n            with self.assertRaisesRegex(ValueError, "missing legacyBaseline"):\n                load_legacy_baseline(\n                    {"schemaVersion": 1},\n                    root / "available.json",\n                    root / "modes.json",\n                )\n\n    def test_malformed_cached_baseline_is_rejected(self):\n        with tempfile.TemporaryDirectory() as temp:\n            root = Path(temp)\n            bad_documents = (\n                [{"title": "Not Canonical!", "sub": True, "dub": False}],\n                [{"title": "canonical", "sub": "yes", "dub": False}],\n                [\n                    {"title": "duplicate", "sub": True, "dub": False},\n                    {"title": "duplicate", "sub": False, "dub": True},\n                ],\n            )\n            for raw in bad_documents:\n                with self.subTest(raw=raw):\n                    with self.assertRaises(ValueError):\n                        load_legacy_baseline(\n                            {"schemaVersion": 1, "legacyBaseline": raw},\n                            root / "available.json",\n                            root / "modes.json",\n                        )\n\n    def test_missing_provider_cache_can_bootstrap_from_legacy_available(self):\n        with tempfile.TemporaryDirectory() as temp:\n            root = Path(temp)\n            available = root / "available.json"\n            modes = root / "modes.json"\n            available.write_text(json.dumps(["Legacy Title"]), encoding="utf-8")\n            modes.write_text(json.dumps({"Legacy Title": {"sub": True, "dub": False}}), encoding="utf-8")\n            baseline = load_legacy_baseline({}, available, modes)\n            self.assertEqual(set(baseline), {"legacy title"})\n\n    def test_existing_incompatible_cache_fails_before_fetcher_creation(self):\n        with tempfile.TemporaryDirectory() as temp:\n            repo = Path(temp)\n            data = repo / "assets" / "data"\n            pipeline = repo / "tools" / "scrapling_provider_pipeline"\n            data.mkdir(parents=True)\n            pipeline.mkdir(parents=True)\n            providers = pipeline / "providers.json"\n            providers.write_text(\n                json.dumps({\n                    "schemaVersion": 1,\n                    "providers": [{\n                        "id": "animefire",\n                        "baseUrl": "https://animefire.example",\n                        "ownedHosts": ["animefire.example"],\n                        "strategy": "animefire",\n                        "roots": ["https://animefire.example/catalog"],\n                        "catalogSelectors": ["article"],\n                        "paginationSelectors": [],\n                    }],\n                }),\n                encoding="utf-8",\n            )\n            (data / "mal_availability_map.json").write_text(\n                json.dumps({"schemaVersion": 1, "entries": []}),\n                encoding="utf-8",\n            )\n            (data / "anime_provider_catalogs.json").write_text(\n                json.dumps({"schemaVersion": 999}),\n                encoding="utf-8",\n            )\n\n            class UnexpectedFetcher:\n                def __init__(self, *args, **kwargs):\n                    raise AssertionError("fetcher must not be created")\n\n            with (\n                patch.object(provider_cache, "HERE", pipeline),\n                patch.object(provider_cache, "ScraplingFetcher", UnexpectedFetcher),\n            ):\n                with self.assertRaisesRegex(SystemExit, "malformed or incompatible"):\n                    provider_cache.main([\n                        "--repo-root", str(repo),\n                        "--providers", str(providers),\n                        "--dry-run",\n                    ])\n\n\nif __name__ == "__main__":\n    unittest.main()\n''', encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
